// Worker entry point. Re-uses the OpenNext fetch handler and adds:
//  * StudyJobWorkflow: durable, retryable execution of long AI jobs.
//  * scheduled(): daily maintenance (audio retention, stuck jobs, sessions).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- generated by `opennextjs-cloudflare build`
// @ts-ignore `.open-next/worker.js` does not exist until the app is built
import { default as handler } from "../.open-next/worker.js";

export { StudyJobWorkflow } from "./workflow";

export default {
  fetch: handler.fetch,
  async scheduled(_controller, env, ctx) {
    const { runMaintenance } = await import("../src/lib/jobs/maintenance");
    ctx.waitUntil(runMaintenance(env));
  },
} satisfies ExportedHandler<CloudflareEnv>;
